ids = list_tickets('open')
ticket_data = []
for id in ids:
  data = get_ticket(id)
  if data['priority'] == 'high':
    ticket_data.append(data)
gold_customers = set()
for t in ticket_data:
  cust = get_customer(t['customer_id'])
  if cust['tier'] == 'gold':
    gold_customers.add(cust['id'])
count = 0
for cid in gold_customers:
  r = send_message(cid, 'We are on it.')
  if r['ok']:
    count += 1
print(count)

